INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zou-state','邹','["邾","邹国","邾国","邾娄","邹"]',NULL,'{"periods":[{"rank":"伯","start":{"year":-1046,"month":1,"confidence":"year"},"end":{"year":-256,"month":12,"confidence":"approximate_year"}}]}','cn','east_asia',-1046,1,NULL,'year',-256,12,NULL,'approximate_year',-12540,-3049,'ochre',NULL,NULL,'周代曹姓诸侯国，春秋称邾或邾娄，战国至孟子时称邹。文公于前614年迁都绎并同年去世；楚灭邹的年代依晚战国通行说，具体年份有异说。早期传世世系及战国晚期君主的世次、在位年代记载不完整。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('meng-ke','孟子','zou-state','[]',NULL,NULL,-372,1,NULL,'year',-289,1,NULL,'year','["思想家"]','战国邹人，名轲，承继并发展孔子学说，游说齐、梁等国，主张仁政、民贵君轻与王道。其言论由弟子记录编成《孟子》，后世尊为亚圣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孟子"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-he','何','zou-state','["邾子何"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾子何，邾隐公之子，前471年由越人立为邾君。《左传·哀公二十四年》记其即位；其退位或卒年及后续继承次序无法由该条直接确定。','[{"label":"《左传·哀公二十四年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-er-shi-si-nian/zhs"},{"label":"邾子何","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AD%90%E4%BD%95"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-jun-qing','庆','zou-state','["邾君庆"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾君庆，春秋早期邾君。枣庄东江春秋墓地出土铜壶铭文称“邾君庆作秦妊礼壶”；现代邾器研究据器铭将其列入邾国君主世系。具体在位年份未考。','[{"label":"冯峰：《说“醴壶”》（北京大学中国考古学研究中心）","url":"https://csca.pku.edu.cn/info/1018/1207.htm"},{"label":"张海：《邾器与两周邾邦史事》","url":"https://www.sohu.com/a/469705297_121124388"},{"label":"邾国君主世系图（据《春秋释例》等）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-kaogong','','zou-state','["邾娄考公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾娄考公，传为邾隐公曾孙。《礼记·檀弓下》记徐君遣使来吊其丧；该记载未给出绝对年代，后世对其世代与年代有不同系年。','[{"label":"《礼记·檀弓下》","url":"https://ctext.org/liji/tan-gong-xia/zhs"},{"label":"邾娄考公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%A8%84%E8%80%83%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','考',NULL,'考公','[]');
