INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-missing-after-mugong-1','？','zou-state','[]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姓名失载的邾国君主。传世世系整理将其列为邹穆公之后、楚灭邾之前的第一位失名君主；具体世次年代未考。','[{"label":"邾国君主世系图（据《春秋释例》等）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"},{"label":"陈良《邹穆公与孟子会晤之后……》（《学习时报》2021-08-13，儒家网转载）：约前382—前330年","url":"https://www.rujiazg.com/article/21221"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-missing-after-mugong-2','？','zou-state','[]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姓名失载的邾国君主。传世世系整理将其列为邹穆公之后、楚灭邾之前的第二位失名君主；具体世次年代未考。','[{"label":"邾国君主世系图（据《春秋释例》等）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"},{"label":"《孟子题辞》所载邾为楚所并（《孟子志》引文）","url":"https://shandong-chorography.org/database/zzmj/section/19/article/7/"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-mu-gong','','zou-state','["邹穆公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邹穆公，孟子在世时的邹君。《孟子·滕文公上》记孟子与其讨论灾年中官吏殉职、民众离散与公家仓廪充实等事；具体在位年代为后世推定。','[{"label":"《孟子·滕文公上》","url":"https://zh.wikisource.org/zh-hans/孟子/滕文公上"},{"label":"孟子志：邾国至邹国沿革及孟子里籍（山东地情档案）","url":"https://shandong-chorography.org/database/zzmj/section/19/article/7/"},{"label":"邹穆公","url":"https://zh.wikipedia.org/wiki/%E9%82%B9%E7%A9%86%E5%85%AC"},{"label":"陈良《邹穆公与孟子会晤之后……》（《学习时报》2021-08-13，儒家网转载）：约前382—前330年","url":"https://www.rujiazg.com/article/21221"},{"label":"邾国君主世系图（据《春秋释例》等）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','穆',NULL,'穆公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r1','挟','zou-state','["邾子挟"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曹姓邾国传统世系所列的始封君。通行说将其受封置于周初；之后相传历非、成、车辅、将新、訾父至武公。早期世系据后世文献辑成，具体在位年及部分世系真实性尚不能确证。','[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r10','？','zou-state','[]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姓名失载的邾国君主。具体世次与在位年代未能由现有可核史料确定。','[]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r11','克','zou-state','["邾安公","邾惠公","邾仪父","邾子克"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾庄公（克，字仪父）为春秋前期邾君；《春秋》鲁隐公元年记鲁与邾仪父会盟，《左传》释其为邾子克，鲁庄公十六年记其卒、子琐继位。世系关系有异说：有说他是夏父元孙，也有说是邾君庆之子；《邹县续志》称其为邾惠公，另有资料称邾安公。','[{"label":"邾国君主世系图（克列作邾庄公，并注明异称）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"},{"label":"《春秋滕薛杞越莒许七国统表·邾世次》（仪父克异称辨析）","url":"https://ctext.org/wiki.pl?chapter=3884730&if=gb&remap=gb"},{"label":"邾安公（异称）","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AE%89%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"},{"label":"邾子克（庄公、惠公异说）","url":"https://zh.wikipedia.org/wiki/邾子克"}]','庄',NULL,'庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r12','琐','zou-state','["邾子琐"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','琐，克之子。传统年表系其在位于前677—前666年，后由邾文公继位；早期君主个人事迹记载较少。','[{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主世系图（列作琐）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"},{"label":"邾子琐（名琐，未载谥号）","url":"https://zh.wikipedia.org/wiki/邾子瑣"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r13','蘧蒢','zou-state','["邾文公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾文公，邾宪公之子。鲁文公十三年（前614）卜迁于绎，迁都有利于民而被占为不利于君；文公同年卒，子貜且继位。迁都事见《左传》，遗址与迁都年代亦见山东地情档案。','[{"label":"《左传·文公十三年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/wen-gong-shi-san-nian/zhs"},{"label":"邾国故城（山东地情档案）","url":"https://shandong-chorography.org/database/a/section/70/article/91/"},{"label":"邾文公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E6%96%87%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','文',NULL,'文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r14','貜且','zou-state','["邾定公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾定公，邾文公之子，于文公卒后继位。传统年表以鲁文公十四年（前613）为其元年，记在位至前573年；邾文公迁绎后，邾国都城在绎。','[{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国故城（山东地情档案）","url":"https://shandong-chorography.org/database/a/section/70/article/91/"},{"label":"邾定公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AE%9A%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','定',NULL,'定公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r15','牼','zou-state','["邾宣公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾宣公，邾定公之子，后继位；传统年表系其在位于前572—前556年。关于其一名，传世版本有牼、瞷等异文。','[{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾宣公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AE%A3%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','宣',NULL,'宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r16','华','zou-state','["邾悼公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾悼公，邾宣公之子，后继位；传统年表系其在位于前555—前541年。','[{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾悼公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E6%82%BC%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','悼',NULL,'悼公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r17','穿','zou-state','["邾庄公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾庄公，邾悼公之子，后继位；传统年表系其在位于前540—前507年，其后邾隐公益继位。','[{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾庄公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%BA%84%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','庄',NULL,'庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r18','益','zou-state','["邾隐公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾隐公，邾庄公之子。吴王夫差立其子革为君后，益一度失位；前473年复位，之后由另一子何继位。传世年表将其分作前506—前487年与前472—前471年两段。','[{"label":"《左传·哀公八年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-ba-nian/zhs"},{"label":"《左传·哀公二十四年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-er-shi-si-nian/zhs"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾隐公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E9%9A%90%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','隐',NULL,'隐公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r19','革','zou-state','["邾桓公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾桓公，邾隐公之子。吴王夫差拥立其为邾君，益复位后革奔越；《左传》记其被立、失位与出奔。','[{"label":"《左传·哀公八年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-ba-nian/zhs"},{"label":"邾桓公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E6%A1%93%E5%85%AC"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','桓',NULL,'桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r2','非','zou-state','["邾子非"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','传统邾国世系称其为挟之子、继为国君，后传位于成。此世系见后世文献汇编，未见可据以确定其在位年份的同期纪年。','[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r3','成','zou-state','["邾子成"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','传统邾国世系称其承继曹非，后传位于车辅；具体在位年代无同期纪年可考，早期世系仍有文献可靠性争议。','[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r4','车辅','zou-state','["邾子车辅"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','传统邾国世系列为曹成之后、将新之前的国君；其个人事迹与在位年份未见同期纪年记载。','[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"},{"label":"邾子车辅（名车辅，未载谥号）","url":"https://zh.wikipedia.org/wiki/邾子車輔"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r5','将新','zou-state','["邾子将新"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','传统邾国世系列为曹车辅之后、訾父之前的国君；其个人事迹与在位年份未见同期纪年记载。','[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r6','訾父','zou-state','["邾子訾父"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','传统邾国世系列为将新之后、武公之前的国君；与武公的父子关系见后世世系整理，具体在位年份无同期纪年可考。','[{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r7','夷父','zou-state','["邾武公"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《公羊传》追述邾娄颜（传统系于武公）及叔术、夏父之间的继承与让国故事；传统年表以周宣王诛颜之年系其卒于前796年。故事中的人物身份与世系细节属于传世叙述。','[{"label":"《春秋公羊传·昭公三十一年》","url":"https://ctext.org/gongyang-zhuan/zhao-gong-san-shi-yi-nian/zhs"},{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]','武',NULL,'武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r8','叔术','zou-state','["邾子叔术"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《公羊传》称叔术受周天子命立为邾君，后让位于夏父，并分得滥地；传文以此称许其让国。传统年表系其在位于前795—前781年，起讫年依年表而非传文精确年月。','[{"label":"《春秋公羊传·昭公三十一年》","url":"https://ctext.org/gongyang-zhuan/zhao-gong-san-shi-yi-nian/zhs"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-r9','夏父','zou-state','["邾子夏父"]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','传统世系称夏父为武公之子；《公羊传》记叔术让国于夏父并以滥地分封。其确切卒年及之后继位年份没有直接纪年证据。','[{"label":"《春秋公羊传·昭公三十一年》","url":"https://ctext.org/gongyang-zhuan/zhao-gong-san-shi-yi-nian/zhs"},{"label":"邾国君主世系与传世文献考","url":"https://zh.wikipedia.org/wiki/邾国"},{"label":"周朝诸侯国君主列表·邾国","url":"https://zh.wikipedia.org/wiki/周朝诸侯国君主列表"},{"label":"邾国君主列表（称谓、本名与记载来源）","url":"https://zh.wikipedia.org/wiki/邾国#國君列表"}]',NULL,NULL,'','[]');
